  function buildQuiz(entries) {
    return entries.map(function (entry, index) {
      const answerIndex = correctPositions[index];
      const options = entry[2].slice();
      options.splice(answerIndex, 0, entry[1]);
      return {
        question: entry[0],
        options: options,
        answerIndex: answerIndex,
        explanation: entry[3],
      };
    });
  }

  Object.keys(additions).forEach(function (weekId) {
    const week = window.COURSE_STUDY[weekId];
    if (!week || !week.en || !Array.isArray(week.quiz) || !Array.isArray(week.en.quiz)) {
      throw new Error("Cannot complete quiz questions for week " + weekId);
    }
    week.quiz.push.apply(week.quiz, buildQuiz(additions[weekId].tr));
    week.en.quiz.push.apply(week.en.quiz, buildQuiz(additions[weekId].en));
    if (week.quiz.length !== 10 || week.en.quiz.length !== 10) {
      throw new Error("Week " + weekId + " must expose exactly ten quiz questions per language");
    }
  });
